#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Android release one-time setup (spec AR-9, issue #58).
# Run from anywhere in the repo:  bash scripts/android-release-wizard.sh
# Safe to re-run: an existing keystore is reused, existing GitHub secrets are kept
# unless you choose to replace them, and values saved in .env.android are offered
# as defaults. Secrets are read with hidden input and never printed.

KEYSTORE_DEFAULT="$HOME/.android-keys/dots-and-boxes-upload.jks"
SECRET_NAMES=(ANDROID_KEYSTORE_BASE64 ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD PLAY_SERVICE_ACCOUNT_JSON)
EXISTING_SECRETS=" "

# secret_exists NAME: true if the repo already has that GitHub secret.
secret_exists() { [[ "$EXISTING_SECRETS" == *" $1 "* ]]; }

# load_env_file: read values from .env.android (when kept) without printing them.
load_env_file() {
  local key value
  for key in ANDROID_KEYSTORE_FILE ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD; do
    if value=$(_existing "$key"); then printf -v "$key" '%s' "$value"; fi
  done
}

# keystore_opens: the keystore file opens with the password and holds the alias.
keystore_opens() {
  KS_PASS="$ANDROID_KEYSTORE_PASSWORD" keytool -list -keystore "$ANDROID_KEYSTORE_FILE" \
    -storepass:env KS_PASS -alias "$ANDROID_KEY_ALIAS" >/dev/null 2>&1
}

# put_secret NAME VALUE: set it unless it already exists and the owner keeps it.
put_secret() {
  local name="$1" value="$2"
  if secret_exists "$name" && ! confirm "$name already exists. Replace it?"; then
    note "kept existing $name"
    return
  fi
  set_secret "$name" "$value"
}

run_wizard() {

TOTAL_STAGES=7

REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || { echo "Run this inside the repo." >&2; exit 1; }
cd "$REPO_ROOT"
ENV_FILE=".env.android"
ANDROID_KEYSTORE_FILE="" ANDROID_KEYSTORE_PASSWORD="" ANDROID_KEY_ALIAS="" ANDROID_KEY_PASSWORD=""
PLAY_SERVICE_ACCOUNT_JSON="" SA_EMAIL=""

banner "Android release: signing keys and Play service account"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check tools"
say "This wizard needs keytool (from a JDK) and the GitHub CLI signed in to this repo."
command -v keytool >/dev/null 2>&1 || { warn "keytool not found: install JDK 17+ and re-run."; exit 1; }
step "keytool: found"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  REPO_NAME=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo "this repo")
  step "gh: signed in, secrets go to $REPO_NAME"
  EXISTING_SECRETS=" $({ gh secret list --json name -q '.[].name' 2>/dev/null || true; } | tr '\n' ' ') "
  for name in "${SECRET_NAMES[@]}"; do
    if secret_exists "$name"; then note "  already set: $name"; fi
  done
else
  warn "gh is missing or not signed in (run: gh auth login). Secrets will be listed as to-do at the end."
fi
if [[ -f "$ENV_FILE" ]]; then
  note "Found $ENV_FILE: its values are offered as defaults."
  load_env_file
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Upload keystore"
say "The upload key signs every AAB you send to Play. Google re-signs the app with"
say "its own key (Play App Signing), so a lost upload key can be reset, but it"
say "takes a support request and days. Keep it outside the repo."
ask ANDROID_KEYSTORE_FILE "Keystore path [default: $KEYSTORE_DEFAULT]:"
ANDROID_KEYSTORE_FILE="${ANDROID_KEYSTORE_FILE:-$KEYSTORE_DEFAULT}"
ANDROID_KEYSTORE_FILE="${ANDROID_KEYSTORE_FILE/#\~/$HOME}"
case "$ANDROID_KEYSTORE_FILE" in
  /*) ;;
  *) ANDROID_KEYSTORE_FILE="$PWD/$ANDROID_KEYSTORE_FILE" ;;
esac
case "$ANDROID_KEYSTORE_FILE" in
  "$REPO_ROOT"/*) warn "That path is inside the repo. Pick one outside it."; exit 1 ;;
esac
ask ANDROID_KEY_ALIAS "Key alias [default: upload]:"
ANDROID_KEY_ALIAS="${ANDROID_KEY_ALIAS:-upload}"

if [[ -f "$ANDROID_KEYSTORE_FILE" ]]; then
  step "Keystore already exists, so this step reuses it."
  while :; do
    ask_secret ANDROID_KEYSTORE_PASSWORD "Keystore password:"
    if keystore_opens; then step "Password and alias check out."; break; fi
    warn "That password doesn't open the keystore, or the alias '$ANDROID_KEY_ALIAS' isn't in it."
    ANDROID_KEYSTORE_PASSWORD=""
    confirm "Try again?" || exit 1
  done
else
  say "Choose a strong password (6+ characters) and save it in your password manager now."
  while :; do
    ask_secret ANDROID_KEYSTORE_PASSWORD "New keystore password:"
    ask_secret KS_CONFIRM "Repeat it:"
    if [[ ${#ANDROID_KEYSTORE_PASSWORD} -lt 6 ]]; then warn "Use at least 6 characters."
    elif [[ "$ANDROID_KEYSTORE_PASSWORD" != "$KS_CONFIRM" ]]; then warn "They don't match."
    else break; fi
    ANDROID_KEYSTORE_PASSWORD=""
  done
  KS_CONFIRM=""
  ask KS_NAME "Your name for the certificate (CN):"
  confirm "Create $ANDROID_KEYSTORE_FILE now?" || exit 1
  mkdir -p "$(dirname "$ANDROID_KEYSTORE_FILE")"
  chmod 700 "$(dirname "$ANDROID_KEYSTORE_FILE")" 2>/dev/null || true
  KS_PASS="$ANDROID_KEYSTORE_PASSWORD" keytool -genkeypair -v \
    -keystore "$ANDROID_KEYSTORE_FILE" -storetype PKCS12 \
    -alias "$ANDROID_KEY_ALIAS" -keyalg RSA -keysize 4096 -validity 10000 \
    -dname "CN=${KS_NAME//,/\\,}" \
    -storepass:env KS_PASS -keypass:env KS_PASS >/dev/null 2>&1 \
    || { warn "keytool failed to create the keystore."; exit 1; }
  chmod 600 "$ANDROID_KEYSTORE_FILE"
  keystore_opens || { warn "The new keystore doesn't open. Delete it and re-run."; exit 1; }
  step "Created $ANDROID_KEYSTORE_FILE (valid about 27 years)."
fi
# PKCS12 keystores use one password for the store and the key.
ANDROID_KEY_PASSWORD="$ANDROID_KEYSTORE_PASSWORD"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Back up the keystore"
say "Do this now; nothing in the repo or CI can recover the file if this machine dies."
step "Add $ANDROID_KEYSTORE_FILE as an attachment to a password-manager entry."
step "In the same entry, save the password and the alias '$ANDROID_KEY_ALIAS'."
note "Optional second copy: an encrypted USB drive or cloud folder. Never commit it or email it."
until confirm "Keystore, password and alias are saved in your password manager?"; do
  warn "Please back it up before continuing."
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: service account and JSON key"
if secret_exists PLAY_SERVICE_ACCOUNT_JSON && ! confirm "PLAY_SERVICE_ACCOUNT_JSON is already set. Create or load a new key?"; then
  note "Skipping: keeping the existing service account secret."
else
  say "CI uploads AABs to Play as a Google Cloud service account."
  open_url "https://console.cloud.google.com/projectcreate"
  step "Create a project (any name, e.g. dots-and-boxes-release), or select one you already use."
  pause "Project selected? Press Enter"
  open_url "https://console.cloud.google.com/apis/library/androidpublisher.googleapis.com"
  step "Check the project picker shows that project, then click Enable on 'Google Play Android Developer API'."
  pause "API enabled? Press Enter"
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
  step "Create service account → name it play-release → Create and continue → skip roles → Done."
  step "Open it → Keys → Add key → Create new key → JSON → Create. A .json file downloads."
  note "If key creation is blocked by an organization policy, use a project outside that organization."
  while :; do
    ask SA_JSON_PATH "Path to the downloaded JSON key file:"
    SA_JSON_PATH="${SA_JSON_PATH/#\~/$HOME}"
    if [[ -f "$SA_JSON_PATH" ]] && grep -q '"type": *"service_account"' "$SA_JSON_PATH"; then break; fi
    warn "That isn't a service account JSON key file."
  done
  PLAY_SERVICE_ACCOUNT_JSON=$(cat "$SA_JSON_PATH")
  SA_EMAIL=$(sed -n 's/.*"client_email": *"\([^"]*\)".*/\1/p' "$SA_JSON_PATH" | head -n1)
  step "Service account: $SA_EMAIL"
  say "After this wizard has stored it as a secret, delete the downloaded file"
  say "(or move it into your password manager)."
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Play Console: invite the service account"
say "Play Console grants API access through Users and permissions."
note "No app yet? Do this after creating it (checklist step 1), and re-run the wizard"
note "then; it reuses the keystore and keeps the secrets already set."
if [[ -n "$SA_EMAIL" ]]; then step "Email to invite: $SA_EMAIL"
else step "Email to invite: the service account's email (IAM → Service accounts, ends in .iam.gserviceaccount.com)."; fi
open_url "https://play.google.com/console/developers/users-and-permissions"
step "Invite new users → paste the email."
step "App permissions → Add app → Dots and Boxes → tick 'Release to testing tracks'"
step "  (and 'Release apps to production' if CI should ever do that) → Apply."
step "Invite user → Send invitation. Service accounts don't need to accept it."
pause "Invited? Press Enter"
step "Then open the app → Test and release → App integrity → Play app signing."
step "It must say Google manages the app signing key (it's set up with your first upload)."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub secrets"
say "Saving the values the Android release workflow reads. Values are never printed."
# the four signing secrets describe one keystore, so they are kept or replaced together: replacing
# only some would leave CI with a password or alias that doesn't open the keystore
SIGNING_SECRETS=(ANDROID_KEYSTORE_BASE64 ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD)
existing_signing=()
for name in "${SIGNING_SECRETS[@]}"; do
  if secret_exists "$name"; then existing_signing+=("$name"); fi
done
if (( ${#existing_signing[@]} )) \
  && ! confirm "Signing secrets already set (${existing_signing[*]}). Replace all four with this keystore?"; then
  note "kept the existing signing secrets"
else
  set_secret ANDROID_KEYSTORE_BASE64 "$(base64 < "$ANDROID_KEYSTORE_FILE" | tr -d '\n')"
  set_secret ANDROID_KEYSTORE_PASSWORD "$ANDROID_KEYSTORE_PASSWORD"
  set_secret ANDROID_KEY_ALIAS "$ANDROID_KEY_ALIAS"
  set_secret ANDROID_KEY_PASSWORD "$ANDROID_KEY_PASSWORD"
fi
if [[ -n "$PLAY_SERVICE_ACCOUNT_JSON" ]]; then
  put_secret PLAY_SERVICE_ACCOUNT_JSON "$PLAY_SERVICE_ACCOUNT_JSON"
elif ! secret_exists PLAY_SERVICE_ACCOUNT_JSON; then
  SKIPPED+=("GitHub secret PLAY_SERVICE_ACCOUNT_JSON (re-run the wizard for the service account stage)")
fi
note "Check with: gh secret list"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Local signed builds (optional)"
say "$ENV_FILE (gitignored) keeps the keystore path and passwords for local signed"
say "builds and for re-running this wizard. Skip it if you only release from CI."
if confirm "Write $ENV_FILE?"; then
  write_env ANDROID_KEYSTORE_FILE "$ANDROID_KEYSTORE_FILE"
  write_env ANDROID_KEYSTORE_PASSWORD "$ANDROID_KEYSTORE_PASSWORD"
  write_env ANDROID_KEY_ALIAS "$ANDROID_KEY_ALIAS"
  write_env ANDROID_KEY_PASSWORD "$ANDROID_KEY_PASSWORD"
  note "Signed local build: set -a; . ./$ENV_FILE; set +a; npm run android:build"
else
  note "Skipped."
fi
pause

ANDROID_KEYSTORE_PASSWORD="" ANDROID_KEY_PASSWORD="" PLAY_SERVICE_ACCOUNT_JSON=""
finish
}

run_wizard "$@"; exit
